package com.aoo.bcg.common.invite;
import com.aoo.bcg.common.config.RoomRuleSnapshot;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class RoomShareSummaryFactoryTest{
@Test void derivesEveryVisibleFieldFromLockedSnapshot(){Map<String,Object>rules=new HashMap<>(Map.of("regionName","内江","playerCount",3,"roundCount",8,"ruleDescription","黑桃3先出"));var snapshot=new RoomRuleSnapshot(1,62,"njpdk-v2","c1","r1","f1","s1","u1",Instant.now(),rules);rules.put("roundCount",99);var summary=new RoomShareSummaryFactory().from(snapshot);assertEquals("内江",summary.regionName());assertEquals(3,summary.playerCount());assertEquals(8,summary.roundCount());assertEquals("njpdk-v2",summary.playVersion());}
@Test void rejectsMissingFieldsInsteadOfInventingDefaults(){Map<String,Object>rules=Map.of("regionName","内江","playerCount",3,"roundCount",8);var snapshot=new RoomRuleSnapshot(1,62,"v","c","r","f","s","u",Instant.now(),rules);assertThrows(IllegalStateException.class,()->new RoomShareSummaryFactory().from(snapshot));}
@Test void sensitiveSourceFieldsNeverEnterProjection(){Map<String,Object>rules=new HashMap<>(Map.of("regionName","内江","playerCount",3,"roundCount",8,"ruleDescription","规则"));rules.put("hands",List.of(1,2));rules.put("accessToken","secret");var snapshot=new RoomRuleSnapshot(1,62,"v","c","r","f","s","u",Instant.now(),rules);String serialized=new com.fasterxml.jackson.databind.ObjectMapper().valueToTree(new RoomShareSummaryFactory().from(snapshot)).toString();assertFalse(serialized.contains("hands"));assertFalse(serialized.contains("secret"));}
@Test void contractDetectsAddedOrForgottenTargetFields(){assertThrows(IllegalStateException.class,()->com.aoo.bcg.common.mapping.FieldConservation.requireExactRecordFields(RoomShareSummary.class,Set.of("gameId")));}
}
